import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Eigene Seitenleisten-Verknüpfungen","description":"UIX-Verknüpfungen zu Home-Assistant-Seiten und externen Webseiten erstellen.","frontmatter":{"title":"Eigene Seitenleisten-Verknüpfungen","description":"UIX-Verknüpfungen zu Home-Assistant-Seiten und externen Webseiten erstellen."},"headers":[],"relativePath":"projects/uix/extras/custom-sidebar-panels.md","filePath":"projects/uix/extras/custom-sidebar-panels.md","lastUpdated":1794571669000}'),s={name:"projects/uix/extras/custom-sidebar-panels.md"};function a(o,e,d,l,u,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="eigene-seitenleisten-verknupfungen" tabindex="-1">Eigene Seitenleisten-Verknüpfungen <a class="header-anchor" href="#eigene-seitenleisten-verknupfungen" aria-label="Permalink to &quot;Eigene Seitenleisten-Verknüpfungen&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">UIX 9.0.0</p><p>Interne und externe Seitenleisten-Verknüpfungen gehören zur stabilen Version <strong>9.0.0</strong> und benötigen <strong>Home Assistant 2026.11.0 oder neuer</strong>. Die unten beschriebene neue Desktop-Beschränkung der Tab-Option stammt aus der Vorschau <strong>9.1.0-beta.1</strong> auf <code>dev</code>.</p></div><p>UIX kann eigene Einträge in der Home-Assistant-Seitenleiste hinzufügen, die eine andere Home-Assistant-Seite oder eine Webseite öffnen. Das erleichtert den Zugriff auf häufig verwendete Seiten unter „Einstellungen“ und auf zugehörige Webdienste.</p><p>Öffne <strong>Einstellungen → Geräte &amp; Dienste → UI eXtension → Konfigurieren</strong> und wähle <strong>Manage custom sidebar panels</strong>. Wähle das Icon und gib Titel und Ziel ein.</p><p>Aktiviere <strong>Admin required</strong>, um den Eintrag auf Administratorkonten zu beschränken.</p><p>Als Ziel sind Home-Assistant-Pfade mit führendem <code>/</code>, etwa <code>/config/dashboard</code>, oder absolute <code>http</code>- und <code>https</code>-URLs erlaubt. Andere URL-Schemata werden nicht akzeptiert.</p><p>Mit <strong>Open in new tab (desktop only)</strong> öffnet sich ein interner Home-Assistant-Pfad in einem neuen Tab des Desktop-Browsers. Der bisherige Home-Assistant-Tab kehrt zur zuvor angezeigten Seite zurück. In der Companion-App navigiert UIX stattdessen innerhalb der App zum HA-Pfad. Für externe Webseiten-URLs wird diese Option nicht verwendet; Webseiten können nicht innerhalb der Companion-App geöffnet werden.</p><div class="info custom-block"><p class="custom-block-title">Neuer Tab und Popup-Sperre</p><p>Ob ein interner HA-Pfad in einem neuen Tab geöffnet werden darf, entscheidet die Popup-Sperre des Desktop-Browsers. UIX versucht dies bei Auswahl des Seitenleisteneintrags, kann es aber nicht garantieren. Bei einer Blockierung wird der HA-Pfad im aktuellen Tab geöffnet.</p></div><p>Jeder Eintrag erhält eine feste interne URL, die UIX verwaltet. Titel, Icon und Ziel lassen sich deshalb ändern, ohne den Eintrag neu anzulegen. Löschen entfernt ihn sofort aus der Seitenleiste.</p><div class="tip custom-block"><p class="custom-block-title">Reihenfolge der Seitenleiste</p><p>Jeder Benutzer kann Einträge über sein Profil <a href="https://www.home-assistant.io/dashboards/dashboards/#reorganizing-items-in-the-sidebar" target="_blank" rel="noreferrer">sortieren und ausblenden</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Weiterleitung</p><p>Ein eigenes Panel ist eine Weiterleitung, keine zweite Kopie der Zielseite und kein iframe. Bei internen Zielen ersetzt UIX die Panel-URL durch das konfigurierte Ziel. Dadurch entsteht im Browserverlauf kein zusätzlicher Weiterleitungsschritt.</p></div><p>Quelle: <a href="https://uix.lf.technology/extras/custom-sidebar-panels/" target="_blank" rel="noreferrer">englische UIX-Originaldokumentation</a>, Lint-Free-Technology/uix, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>.</p><p>Ergänzender Quellenabgleich vom 07.11.2026: <a href="https://github.com/Lint-Free-Technology/uix/commit/e7b5bdd811a53960e9559c53a354c7855c537286" target="_blank" rel="noreferrer"><code>dev e7b5bdd</code></a>, einschließlich <a href="https://github.com/Lint-Free-Technology/uix/commit/1d53592b241ec8666b34d67056671bb37d1c2a1f" target="_blank" rel="noreferrer"><code>1d53592</code></a>. Die Vorschauangabe ersetzt keine stabile Versionsfreigabe.</p>',13)])])}const h=n(s,[["render",a]]);export{g as __pageData,h as default};
